"""File templates for `gg new --template cortex-m`. The text is the same as `examples/embedded/cortex_m/` (a test keeps them equal)."""

CORTEX_M_MAIN = '# A bare-metal Cortex-M4 program: reset handler, interrupt handlers, memory-mapped I/O, initialized statics.\n#\n#   gg build main.gg --no-std --target cortex-m4 --linker-script link.ld -o firmware.elf\n#\n# Nothing here needs libc: `--no-std` leaves out `print` and the heap. `link.ld` builds the vector table at the start\n# of flash from the exported names below (`reset`, `NMI`, `HardFault`, `SysTick`, ...: any it does not find falls back to\n# `DefaultHandler`), and defines the stack top and the `.data` / `.bss` boundaries that `reset` initializes.\n\nstatic ticks: u32 = 0\nstatic greeting: u32 = 0xC0FFEE\n\n# GPIO output register of a typical Cortex-M part (an address from the chip\'s reference manual).\nconst GPIO_ODR: usize = 0x40020014\n\nfn gpio_write(value: u32):\n    unsafe:\n        volatile_write[u32](int_to_ptr[*mut u32](GPIO_ODR), value)\n\n# The addresses the linker script defines. `ldr r, =symbol` loads one.\nfn data_load_start() -> usize:\n    unsafe:\n        return asm[usize]("ldr $0, =_sidata", "=r")\n\nfn data_start() -> usize:\n    unsafe:\n        return asm[usize]("ldr $0, =_sdata", "=r")\n\nfn data_end() -> usize:\n    unsafe:\n        return asm[usize]("ldr $0, =_edata", "=r")\n\nfn bss_start() -> usize:\n    unsafe:\n        return asm[usize]("ldr $0, =_sbss", "=r")\n\nfn bss_end() -> usize:\n    unsafe:\n        return asm[usize]("ldr $0, =_ebss", "=r")\n\n@export("reset")\nfn reset():\n    unsafe:\n        # copy the initial values of statics from flash to RAM, then clear the zero-initialized ones\n        src = int_to_ptr[*u32](data_load_start())\n        dst = int_to_ptr[*mut u32](data_start())\n        words = (data_end() - data_start()) / 4\n        for i in 0..words:\n            dst[i] = src[i]\n        zero = int_to_ptr[*mut u32](bss_start())\n        zwords = (bss_end() - bss_start()) / 4\n        for i in 0..zwords:\n            zero[i] = 0\n    main()\n    while true:\n        pass\n\n@interrupt\nfn SysTick():\n    unsafe:\n        ticks = ticks + 1\n\n@interrupt\nfn DefaultHandler():\n    while true:\n        pass\n\n@panic_handler\nfn on_panic():\n    gpio_write(0xFFFF)\n    while true:\n        pass\n\nfn main():\n    unsafe:\n        gpio_write(greeting & 1)\n    n: u32 = 0\n    while true:\n        n += 1\n        unsafe:\n            gpio_write(n & ticks)\n'

CORTEX_M_LINK = '/* Linker script for a Cortex-M4 with 256 KiB of flash at 0x08000000 and 64 KiB of RAM at 0x20000000.\n   Change the two lengths and origins for your chip. */\nMEMORY\n{\n  FLASH (rx)  : ORIGIN = 0x08000000, LENGTH = 256K\n  RAM   (rwx) : ORIGIN = 0x20000000, LENGTH = 64K\n}\n\nENTRY(reset)\n_estack = ORIGIN(RAM) + LENGTH(RAM);\n\n/* Interrupt handlers the program does not define fall back to DefaultHandler. */\nPROVIDE(NMI = DefaultHandler);\nPROVIDE(HardFault = DefaultHandler);\nPROVIDE(MemManage = DefaultHandler);\nPROVIDE(BusFault = DefaultHandler);\nPROVIDE(UsageFault = DefaultHandler);\nPROVIDE(SVCall = DefaultHandler);\nPROVIDE(DebugMon = DefaultHandler);\nPROVIDE(PendSV = DefaultHandler);\nPROVIDE(SysTick = DefaultHandler);\n\nSECTIONS\n{\n  .vectors : {\n    LONG(_estack);\n    LONG(reset);\n    LONG(NMI);\n    LONG(HardFault);\n    LONG(MemManage);\n    LONG(BusFault);\n    LONG(UsageFault);\n    LONG(0); LONG(0); LONG(0); LONG(0);\n    LONG(SVCall);\n    LONG(DebugMon);\n    LONG(0);\n    LONG(PendSV);\n    LONG(SysTick);\n    KEEP(*(.isr_vector))      /* device interrupts: a table of `fn()` in a `@section(".isr_vector")` static */\n  } > FLASH\n\n  .text : {\n    *(.text*)\n    *(.rodata*)\n    . = ALIGN(4);\n  } > FLASH\n\n  _sidata = LOADADDR(.data);\n  .data : {\n    _sdata = .;\n    *(.data*)\n    . = ALIGN(4);\n    _edata = .;\n  } > RAM AT > FLASH\n\n  .bss (NOLOAD) : {\n    _sbss = .;\n    *(.bss*)\n    *(COMMON)\n    . = ALIGN(4);\n    _ebss = .;\n  } > RAM\n\n  /DISCARD/ : { *(.ARM.exidx*) *(.comment) }\n}\n'

CORTEX_M_README = """# @NAME@

A bare-metal Cortex-M4 program. Edit the memory sizes in `link.ld` for your chip, then:

    gg build --no-std --target cortex-m4 --linker-script link.ld -o firmware.elf

Inline assembly for ARM needs the outside clang: set `GG_BACKEND=clang`. Check the limits with
`--forbid-heap --forbid-recursion --max-stack 1024` and `gg stack-usage src/main.gg --no-std --target cortex-m4`.
"""
